import { describe, expect, test } from 'bun:test';
import { createHmac } from 'crypto';
import type { IncomingMessage } from 'http';
import PlivoWebSocketServer, { type PlivoWebSocketServerOptions } from './index';

// Vectors generated by Plivo's server-side signing code.
const authToken = 'test-auth-token';
const nonce = '12345678901234567890';

const sign = (url: string) => createHmac('sha256', authToken).update(`${url}.${nonce}`).digest('base64');

function createServer(options: Partial<PlivoWebSocketServerOptions> = {}) {
  return new PlivoWebSocketServer({ noServer: true, validateSignature: true, authToken, ...options });
}

function validate(
  server: PlivoWebSocketServer,
  url: string,
  signature: string,
  headers: Record<string, string> = {},
  encrypted = false,
): boolean {
  const request = {
    method: 'GET',
    url,
    headers: {
      host: 'example.com',
      'x-plivo-signature-v3': signature,
      'x-plivo-signature-v3-nonce': nonce,
      ...headers,
    },
    socket: { encrypted },
  } as unknown as IncomingMessage;
  return (server as any).validateConnectionSignature(request);
}

describe('validateConnectionSignature', () => {
  const tls = { 'x-forwarded-proto': 'https' };

  test.each([
    ['wss with query', '/media/stream?tenant=42&env=prod', 'Ni6eSQI9zg/LjUt95Nlt5nTYA7FpL6CQuY2F+Yy3jyc='],
    ['wss without query', '/media/stream', 'paNuAIW+AAlyCT4lFH8ZrCvzj3gkNuvrX0r877mN3nM='],
    ['encoded query', '/s?sig=abc%3D%3D&name=John+Doe', 'WkbN9mLc0kqBHtOjlD4GiUIvDkZ+cSfqUsEKrF8ixmY='],
    ['encoded path', '/my%20stream/ws?id=1', '5hGH/IknEopkorKviPg1OTVLJvkZ/oqs3GBHF9Si4mw='],
    ['encoded slash in path', '/a%2Fb/ws?q=1', 'ZnGd8sbUoc4m+gsJK4smUKQF51bEy5S2dSEYnS/FZdc='],
    ['no path', '/', 'mXPltZtATpEE0xZ2FUiuVHgIis/d14y8t/rtESnFGjU='],
  ])('accepts %s', (_, url, signature) => {
    expect(validate(createServer(), url, signature, tls)).toBe(true);
  });

  test('accepts wss with port', () => {
    const signature = 'd4mqJrd9gtwO+Dfc7IT4u144WmmoPrnCjYUTmM3HBSk=';
    expect(validate(createServer(), '/ws/?b=2&a=1', signature, { ...tls, host: 'example.com:8443' })).toBe(true);
  });

  test('picks ws or wss from x-forwarded-proto, then the socket', () => {
    const wss = 'Ni6eSQI9zg/LjUt95Nlt5nTYA7FpL6CQuY2F+Yy3jyc=';
    const ws = 'De3cjnXuPrS4pSTyrva6wFEYh9CpRgvlyaQ1gct9auo=';
    const url = '/media/stream?tenant=42&env=prod';
    const server = createServer();

    expect(validate(server, url, ws)).toBe(true);
    expect(validate(server, url, wss)).toBe(false);
    expect(validate(server, url, wss, {}, true)).toBe(true);
    expect(validate(server, url, ws, { 'x-forwarded-proto': 'http' }, true)).toBe(true);
  });

  test('uses publicUrl instead of the request scheme and host', () => {
    const signature = 'Ni6eSQI9zg/LjUt95Nlt5nTYA7FpL6CQuY2F+Yy3jyc=';
    const server = createServer({ publicUrl: 'wss://example.com/' });
    expect(validate(server, '/media/stream?tenant=42&env=prod', signature, { host: 'internal:8080' })).toBe(true);
  });

  test('accepts the legacy http signature only when allowLegacySignature is on', () => {
    const url = '/media/stream?tenant=42&env=prod';
    const legacy = sign('http://example.com/media/stream');

    expect(validate(createServer(), url, legacy, tls)).toBe(true);
    expect(validate(createServer({ allowLegacySignature: false }), url, legacy, tls)).toBe(false);
  });

  test('accepts either of two comma-separated signatures', () => {
    const signature = 'paNuAIW+AAlyCT4lFH8ZrCvzj3gkNuvrX0r877mN3nM=';
    expect(validate(createServer(), '/media/stream', `${sign('wrong')},${signature}`, tls)).toBe(true);
  });

  test('rejects a wrong signature', () => {
    expect(validate(createServer(), '/media/stream', sign('wss://example.com/other'), tls)).toBe(false);
  });

  test('rejects missing signature headers', () => {
    expect(validate(createServer(), '/media/stream', '', tls)).toBe(false);
  });
});
